<?php
/**
 * `POST /bcm/v1/selection` (SPEC §9.1, §12.1): resolves a selection to its
 * count and a signed token. The body is either the grid's conditions —
 * search, mode and the `/products` filter arguments, generated by
 * RouteSchema::selection_args() — or an explicit `ids` list; with `ids` the
 * filter arguments are ignored. The answer is `{ count, token }`: a filter's
 * count is the cached `COUNT(*)` the grid shows (Query\CountCache), an id
 * list's the number of distinct ids, kept in the order given. The token
 * (Selection\SelectionToken) is what preview and apply take, so they act on
 * exactly this selection, for this user, until it expires.
 *
 * It precedes a write, so it needs the write capability (Access::can_write).
 * A selection of more than 100,000 objects is refused 400
 * `bcm_selection_too_large`, naming the count.
 *
 * @package BulkCatalogueManager
 * @license GPL-3.0-or-later
 */

declare( strict_types = 1 );

namespace BulkCatalogueManager\Rest;

use BulkCatalogueManager\Fields\Registry;
use BulkCatalogueManager\Query\CountCache;
use BulkCatalogueManager\Query\Criteria;
use BulkCatalogueManager\Query\ProductQuery;
use BulkCatalogueManager\Selection\Selection;
use BulkCatalogueManager\Selection\SelectionToken;

defined( 'ABSPATH' ) || exit;

/**
 * The selection route.
 */
final class SelectionController implements Controller {
	/**
	 * The route, under Access::REST_NAMESPACE.
	 */
	public const ROUTE = '/selection';

	/**
	 * The refusal code for a selection above Selection::MAX_OBJECTS.
	 */
	public const TOO_LARGE = 'bcm_selection_too_large';

	/**
	 * Arguments generator.
	 *
	 * @var RouteSchema
	 */
	private RouteSchema $schema;

	/**
	 * The count cache.
	 *
	 * @var CountCache
	 */
	private CountCache $counts;

	/**
	 * Build over a registry.
	 *
	 * @param Registry        $registry Field registry.
	 * @param CountCache|null $counts   Count cache; the plugin's by default.
	 */
	public function __construct( Registry $registry, ?CountCache $counts = null ) {
		$this->schema = new RouteSchema( $registry );
		$this->counts = $counts ?? new CountCache();
	}

	/**
	 * Add the route through the registrar.
	 *
	 * @param Routes $routes The registrar.
	 */
	public function register_routes( Routes $routes ): void {
		$routes->add(
			self::ROUTE,
			[
				[
					'methods'             => 'POST',
					'callback'            => [ $this, 'create_item' ],
					'permission_callback' => [ Access::class, 'can_write' ],
					'args'                => $this->schema->selection_args(),
				],
			]
		);
	}

	/**
	 * `{ count, token }` for the posted selection.
	 *
	 * @param \WP_REST_Request $request The request, its arguments validated and sanitised by core.
	 */
	public function create_item( \WP_REST_Request $request ): \WP_REST_Response|\WP_Error {
		$params = array_intersect_key( $request->get_params(), $this->schema->selection_args() );
		try {
			if ( isset( $params['ids'] ) ) {
				$selection = Selection::of_ids( (array) $params['ids'] );
			} else {
				unset( $params['ids'] );
				$query     = new ProductQuery( Criteria::from_array( $this->schema->criteria_input( $params ) ) );
				$selection = Selection::of_filter( $query->criteria(), $this->counts->total( $query ) );
			}
		} catch ( \InvalidArgumentException $e ) {
			return Refusal::invalid(
				'bcm_invalid_value',
				__( 'These products or filters could not be selected. Clear the filters, choose the products again and try again.', 'bulk-catalogue-manager-for-woocommerce' ),
				[ 'details' => $e->getMessage() ]
			);
		}

		if ( $selection->too_large() ) {
			return Refusal::invalid(
				self::TOO_LARGE,
				sprintf(
					/* translators: 1: how many products the selection holds, such as "100,001"; 2: the most one change may hold, "100,000". */
					__( 'This selection holds %1$s products, more than the %2$s one change can include. Add a filter to narrow it and try again.', 'bulk-catalogue-manager-for-woocommerce' ),
					number_format_i18n( $selection->count ),
					number_format_i18n( Selection::MAX_OBJECTS )
				),
				[
					'count' => $selection->count,
					'limit' => Selection::MAX_OBJECTS,
				]
			);
		}

		return new \WP_REST_Response(
			[
				'count' => $selection->count,
				'token' => SelectionToken::mint( $selection ),
			],
			200
		);
	}
}
